const input = $json;
const operation = input.operation || 'search_emails';
const userId = input.user_id || '';
const query = input.query || '';
const limit = Math.min(parseInt(input.limit) || 5, 100);
const dateFrom = input.date_from || null;
const dateTo = input.date_to || null;
const mailboxId = input.mailbox_id || null;
const uid = input.uid || null;
const host = input.host || null;
const port = input.port || 993;
const username = input.username || null;
const password = input.password || null;
const ssl = input.ssl !== false;
// PROJ-73: Normalize sort mode (allowlisted) — 'recency' sorts by date instead
// of relevance score; anything else (including missing/unknown) is 'relevance'.
function normSortMode(val) {
  return String(val || '').toLowerCase().trim() === 'recency' ? 'recency' : 'relevance';
}
const sortMode = normSortMode(input.sort_mode);
return [{ json: { operation, userId, query, limit, dateFrom, dateTo, mailboxId, uid, host, port, username, password, ssl, sortMode, __via_webhook: input.__via_webhook === true } }];

// Weaviate search over authorized mailboxes — relevance or recency mode
const axios = require('axios');
const input = $('Input Normalizer').first().json;
const accessRows = $input.all().map(i => i.json);
const mailboxIds = accessRows.map(r => r.mailbox_id).filter(Boolean);

if (mailboxIds.length === 0) {
  return [{ json: { results: [], error: null } }];
}

const WEAVIATE_URL = 'http://weaviate:8080';
const { query, limit, dateFrom, dateTo, sortMode } = input;

// PROJ-73: recency mode sorts by date instead of relevance score.
const isRecency = sortMode === 'recency';
const hasQuery = !!(query && query.trim());
// With a content criterion in recency mode, keep today's hybrid matching unchanged
// but fetch a larger candidate pool (technical cap) before re-sorting by date, so a
// more-recent-but-lower-score match isn't excluded by the query-side limit.
const TECHNICAL_CAP = 100;
const fetchLimit = (isRecency && hasQuery) ? TECHNICAL_CAP : limit;
// Pure recency with no content criterion skips hybrid entirely — an empty/invented
// query text can then never suppress results, since we never search by text at all.
const skipHybrid = isRecency && !hasQuery;

// Build base filter conditions (mailbox scope + date range), shared by every query variant.
const mailboxFilter = mailboxIds.length === 1
  ? `{ path: ["mailboxId"], operator: Equal, valueText: "${mailboxIds[0]}" }`
  : `{ operator: Or, operands: [${mailboxIds.map(id => `{ path: ["mailboxId"], operator: Equal, valueText: "${id}" }`).join(', ')}] }`;

const dateConds = [];
if (dateFrom) dateConds.push(`{ path: ["date"], operator: GreaterThanEqual, valueDate: "${dateFrom}T00:00:00Z" }`);
if (dateTo)   dateConds.push(`{ path: ["date"], operator: LessThanEqual, valueDate: "${dateTo}T23:59:59Z" }`);

function whereFromConds(conds) {
  if (conds.length === 0) return '';
  if (conds.length === 1) return `where: ${conds[0]}`;
  return `where: { operator: And, operands: [${conds.join(', ')}] }`;
}

const emailFields = 'messageId mailboxId imapUid subject sender date category summary attachments hasAttachments';

let gql;
let aliased = false;
if (skipHybrid) {
  // No hybrid/vector search involved, so no score is emitted — _additional only
  // requests id. Weaviate's `sort` reliably returns the true global top-N by date
  // for emails that HAVE the date field set (scales to large mailboxes), but it
  // silently EXCLUDES emails that never had the field set at all, rather than
  // ranking them last. So we fetch both halves in one aliased GraphQL request:
  // `dated` (sorted, authoritative ordering) and `undated` (explicit IsNull filter,
  // always ranked after dated results by the caller's date-descending JS sort).
  aliased = true;
  const baseConds = [mailboxFilter, ...dateConds];
  const datedWhere = whereFromConds(baseConds);
  const datedQuery = `dated: Email(${datedWhere} sort: [{ path: ["date"], order: desc }] limit: ${fetchLimit}) { _additional { id } ${emailFields} }`;

  const undatedConds = [...baseConds, `{ path: ["date"], operator: IsNull, valueBoolean: true }`];
  const undatedWhere = whereFromConds(undatedConds);
  const undatedQuery = `undated: Email(${undatedWhere} limit: ${fetchLimit}) { _additional { id } ${emailFields} }`;

  gql = `{ Get { ${datedQuery} ${undatedQuery} } }`;
} else {
  const whereClause = whereFromConds([mailboxFilter, ...dateConds]);
  const escapedQuery = query.replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\n/g, ' ').replace(/\r/g, '').replace(/[\x00-\x1f]/g, '');
  gql = `{ Get { Email(hybrid: { query: "${escapedQuery}", alpha: 0.5 } ${whereClause} limit: ${fetchLimit}) { _additional { id score } ${emailFields} } } }`;
}

try {
  const res = await axios.post(`${WEAVIATE_URL}/v1/graphql`, { query: gql }, { headers: { 'Content-Type': 'application/json' }, timeout: 30000 });
  const emails = aliased
    ? [...(res.data?.data?.Get?.dated || []), ...(res.data?.data?.Get?.undated || [])]
    : (res.data?.data?.Get?.Email || []);
  let results = emails.map(e => ({
    weaviate_id: e._additional?.id,
    mailbox_id: e.mailboxId,
    imap_uid: e.imapUid,
    message_id: e.messageId,
    subject: e.subject,
    sender: e.sender,
    date: e.date,
    category: e.category,
    summary: e.summary,
    has_attachments: e.hasAttachments,
    attachments: e.attachments || []
  }));

  // Recency mode re-sorts the (possibly merged dated+undated) candidates by date
  // descending and trims to the requested limit; relevance mode keeps the existing
  // behavior (Weaviate's implicit hybrid-score ordering, already capped by fetchLimit).
  if (isRecency) {
    results.sort((a, b) => {
      const da = a.date ? Date.parse(a.date) : 0;
      const db = b.date ? Date.parse(b.date) : 0;
      return db - da;
    });
    results = results.slice(0, limit);
  }

  return [{ json: { results, error: null } }];
} catch(err) {
  return [{ json: { results: [], error: err.message } }];
}

// Fetch full email body from IMAP via alice-mail-reader
// Requires mailbox credentials from Postgres
const axios = require('axios');
const input = $('Input Normalizer').first().json;
const { userId, mailboxId, uid } = input;

if (!mailboxId || !uid) {
  return [{ json: { body: null, error: 'mailbox_id und uid sind erforderlich' } }];
}

try {
  // Get mailbox credentials
  const pgRes = await axios.post('http://n8n:5678/webhook-test/dummy', {}).catch(() => null); // placeholder
  // We use a different approach: credentials come pre-resolved from the caller (alice-chat-stream passes them),
  // or we fetch them in the PG node below
  return [{ json: { _fetch_body: true, mailboxId, uid } }];
} catch(e) {
  return [{ json: { body: null, error: e.message } }];
}

const creds = $json;
if (!creds.imap_host) return [{ json: { body: null, error: 'Postfach nicht gefunden oder kein Zugriff' } }];
// Decrypt password
const crypto = require('crypto');
const KEY = crypto.createHash('sha256').update('alice-mail-enc-key-2026').digest();
const [ivHex, encHex] = creds.password_enc.split(':');
const iv = Buffer.from(ivHex, 'hex');
const enc = Buffer.from(encHex, 'hex');
const decipher = crypto.createDecipheriv('aes-256-cbc', KEY, iv);
const password = Buffer.concat([decipher.update(enc), decipher.final()]).toString('utf8');
const uid = $('Prep: Get Body').first().json.uid;
return [{ json: { host: creds.imap_host, port: creds.imap_port, username: creds.imap_username, password, ssl: creds.ssl_enabled, uid } }];
